def decimal_to_exponential(number: float) -> tuple:
    """
    Truncate the number and return it together with its equivalent exponential
    in format (mantissa, exponent)
    """
    mantissa = truncate_number(number)
    exponent = int(math.floor(math.log10(abs(mantissa))))
    if mantissa == 0:
        return (0, exponent)
    if mantissa > 0:
        sign = "+"
    else:
        sign = "-"
    return (sign, mantissa, exponent)


