def mean(numbers: List[float]) -> float:
    """ Compute the mean average
    """
    return sum(numbers) / len(numbers)


def median(numbers: List[float]) -> float:
    """ Median of input numbers
    """
    return float(sorted(numbers)[len(numbers) // 2]) if len(numbers) % 2
    else float(sorted(numbers)[len(numbers) // 2 - 1 : len(numbers) // 2 + 1][0])


def variance(numbers: List[float]) -> float:
    """ Calculate the variance of a dataset:
    1/len(dataset) * sum of (x - mean) ** 2
    """
    return sum([(x - mean(numbers)) ** 2 for x in numbers]) / len(numbers)

