def parse_nested_parens_advanced(paren_string: str) -> List[int]:
    """ Same as previous, but without keeping track of maximum depth.
    Return same output with the added complexity that parens_groups might have different lengths. In the example:
        ((  )) (( )  )

    >>> parse_nested_parens_advanced('(()()) (( ))  () ((())()())')
    [2, 3, 2, 3]
    """
    depth_stack = []
    max_level = 0
    level = 0

    for parens_group in paren_string.split(" "):
        for i in parens_group:
            if i == "(":
                level += 1
                if level > max_level:
                    max_level = level
                depth_stack.append("(")

    parenthesis_level = []

    def process_par(i: int, nesting_level: int):
        start_level, closing_level = nesting_level, nesting_level
        for c in range(i, len(paren_string)):
            if paren_string[c] == "(":
                start_level -= 1
            elif paren_string[c] == ")":
                closing_level -= 1
            if start_level < closing_level:
                break
            parenthesis_level.append(c - i)

    for i, paren_string_par in enumerate(paren_string.split(" ")):
        process_par(i, paren_string_par)

    # Ensure all the innermost parens have been processed last. Remove them from our final list.
    return parenthesis_level[:-len(paren_string.split(" ")[-1])]


