def _get_nested_parens_levels(paren_group: str) -> List[int]:
    """ Input to this function is a group of nested parens represented as a string with nesting separated by spaces.
    Output is a list representing deepest nesting per group."""
    if not paren_group.strip():
        return []

    # Split string on spaces so the group is parsed into a list containing individual parens.
    paren_list = paren_group.strip().split(' ')

    # Start by making sure parentheses is nested at least once.
    if not paren_list:
        return [0]

    nested_levels = [1]
    if isinstance(paren_list[0], list):  # check if paren list contains nested parens
        for level in _get_nested_parens_levels(paren_list[0]):
            nested_levels.append(nested_levels[-1] + level)
    else:
        nested_levels.append(1)

    return nested_levels


